using System.Security.Claims;using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;using ProMaxx2.QA.Application.Execution;using ProMaxx2.QA.Application.Projects;
namespace ProMaxx2.QA.Api.Controllers;
[ApiController,Route("api/v1"),Authorize(Policy="ExecutionRun")]
public sealed class TestCyclesController(TestCycleService service):ControllerBase
{
 [HttpGet("test-environments")]public Task<IReadOnlyList<EnvironmentDto>>Environments([FromQuery]Guid?projectId,CancellationToken ct)=>service.EnvironmentsAsync(projectId,ct);[HttpPost("test-environments")]public async Task<ActionResult<EnvironmentDto>>CreateEnvironment(SaveEnvironmentRequest r,CancellationToken ct)=>Ok(await service.CreateEnvironmentAsync(r,ct));
 [HttpGet("test-cycles")]public Task<IReadOnlyList<TestCycleDto>>List([FromQuery]Guid?projectId,CancellationToken ct)=>service.ListAsync(projectId,ct);[HttpPost("test-cycles")]public async Task<ActionResult<TestCycleDto>>Create(SaveTestCycleRequest r,CancellationToken ct){try{return Ok(await service.CreateAsync(r,UserId(),ct));}catch(DuplicateCodeException ex){return Conflict(new ProblemDetails{Title="รหัส Test Cycle ซ้ำ",Detail=ex.Message,Status=409});}catch(Exception ex)when(ex is ArgumentException or EntityNotFoundException){return BadRequest(new ProblemDetails{Title="ข้อมูล Test Cycle ไม่ถูกต้อง",Detail=ex.Message,Status=400});}}[HttpPut("test-cycles/{id:guid}")]public async Task<ActionResult<TestCycleDto>>Update(Guid id,SaveTestCycleRequest r,CancellationToken ct){try{return Ok(await service.UpdateAsync(id,r,ct));}catch(EntityNotFoundException){return NotFound();}}[HttpPost("test-cycles/{id:guid}/status")]public async Task<ActionResult<TestCycleDto>>Status(Guid id,ChangeCycleStatusRequest r,CancellationToken ct){try{return Ok(await service.StatusAsync(id,r.Status,ct));}catch(EntityNotFoundException){return NotFound();}catch(ArgumentException ex){return BadRequest(new ProblemDetails{Title="สถานะไม่ถูกต้อง",Detail=ex.Message,Status=400});}}[HttpDelete("test-cycles/{id:guid}")]public async Task<IActionResult>Delete(Guid id,CancellationToken ct){try{await service.DeleteAsync(id,UserId(),ct);return NoContent();}catch(EntityNotFoundException){return NotFound();}}private Guid?UserId()=>Guid.TryParse(User.FindFirstValue(ClaimTypes.NameIdentifier)??User.FindFirstValue("sub"),out var id)?id:null;
}
